1	//! Run command implementation.
2	//!
3	//! The `bivvy run` command executes setup workflows.
4	
5	use std::collections::{HashMap, HashSet};
6	use std::path::{Path, PathBuf};
7	
8	use crate::cli::args::RunArgs;
9	#[cfg(test)]
10	use crate::config::load_merged_config;
11	use crate::config::{
12	    evaluate_vars, load_for_run_with_trust, load_project_config, ConfigPaths, Discovery,
13	    ExtendsResolver, InterpolationContext, TrustPolicy, TrustStore,
14	};
15	use crate::environment::resolver::ResolvedEnvironment;
16	use crate::error::{BivvyError, Result};
17	use crate::registry::Registry;
18	use crate::requirements::checker::GapChecker;
19	use crate::requirements::probe::EnvironmentProbe;
20	use crate::requirements::registry::RequirementRegistry;
21	use crate::runner::display::{
22	    NonInteractiveWorkflowDisplay, RunHeader, RunSummary, StepSummary, TerminalWorkflowDisplay,
23	    WorkflowDisplay,
24	};
25	use crate::runner::{RunOptions, SkipBehavior, WorkflowRunner};
26	use crate::state::{ProjectId, StateStore};
27	use crate::steps::ResolvedStep;
28	use crate::ui::surface::TerminalSurface;
29	use crate::ui::{hints, OutputMode, StatusKind, UserInterface};
30	
31	use super::dispatcher::{Command, CommandResult};
32	
33	/// The run command implementation.
34	pub struct RunCommand {
35	    project_root: PathBuf,
36	    args: RunArgs,
37	    trust_policy: TrustPolicy,
38	    config_override: Option<PathBuf>,
39	}
40	
41	impl RunCommand {
42	    /// Create a new run command.
43	    pub fn new(project_root: &Path, args: RunArgs) -> Self {
44	        Self {
45	            project_root: project_root.to_path_buf(),
46	            args,
47	            trust_policy: TrustPolicy::Prompt,
48	            config_override: None,
49	        }
50	    }
51	
52	    /// Create a new run command with a specific trust policy.
53	    pub fn with_trust_policy(mut self, policy: TrustPolicy) -> Self {
54	        self.trust_policy = policy;
55	        self
56	    }
57	
58	    /// Set an override config path.
59	    pub fn with_config_override(mut self, config_override: Option<PathBuf>) -> Self {
60	        self.config_override = config_override;
61	        self
62	    }
63	
64	    /// Get the project root path.
65	    pub fn project_root(&self) -> &Path {
66	        &self.project_root
67	    }
68	
69	    /// Get the command arguments.
70	    pub fn args(&self) -> &RunArgs {
71	        &self.args
72	    }
73	
74	    /// Build run options from args.
75	    fn build_options(&self, config: &crate::config::BivvyConfig) -> RunOptions {
76	        let skip_behavior = match self.args.skip_behavior.as_str() {
77	            "skip_only" => SkipBehavior::SkipOnly,
78	            "run_anyway" => SkipBehavior::RunAnyway,
79	            _ => SkipBehavior::SkipWithDependents,
80	        };
81	
82	        // CLI flags override config: --diagnostic-funnel forces on,
83	        // --no-diagnostic-funnel forces off, otherwise use config value.
84	        let diagnostic_funnel = if self.args.diagnostic_funnel {
85	            true
86	        } else if self.args.no_diagnostic_funnel {
87	            false
88	        } else {
89	            config.settings.execution.diagnostic_funnel
90	        };
91	
92	        let (force, force_all) =
93	            merge_force_directives(&self.args, config.workflows.get(&self.args.workflow));
94	
95	        RunOptions {
96	            workflow: Some(self.args.workflow.clone()),
97	            only: self.args.only.iter().cloned().collect(),
98	            skip: self.args.skip.iter().cloned().collect(),
99	            skip_behavior,
100	            force,
101	            force_all,
102	            dry_run: self.args.dry_run,
103	            provided_requirements: HashSet::new(),
104	            active_environment: None,
105	            diagnostic_funnel,
106	            fresh: self.args.fresh,
107	        }
108	    }
109	
110	    /// Resolve the target environment using the priority chain.
111	    fn resolve_environment(&self, config: &crate::config::BivvyConfig) -> ResolvedEnvironment {
112	        ResolvedEnvironment::resolve_from_config(self.args.env.as_deref(), &config.settings)
113	    }
114	
115	    /// Resolve steps from configuration.
116	    ///
117	    /// Steps with a `template` field are resolved through the Registry,
118	    /// which merges template defaults with config overrides. Steps without
119	    /// a template are treated as inline definitions.
120	    fn resolve_steps(
121	        &self,
122	        config: &crate::config::BivvyConfig,
123	        environment: Option<&str>,
124	    ) -> Result<HashMap<String, ResolvedStep>> {
125	        let registry = if config.template_sources.is_empty() {
126	            Registry::new(Some(&self.project_root))?
127	        } else {
128	            Registry::with_remote_sources(Some(&self.project_root), &config.template_sources)?
129	        };
130	
131	        let defaults = &config.settings.defaults;
132	        // Resolve the effective global rerun window: prefer defaults.rerun_window,
133	        // fall back to execution.default_rerun_window for backward compatibility.
134	        let global_rerun_window = defaults.rerun_window.as_deref().or(config
135	            .settings
136	            .execution
137	            .default_rerun_window
138	            .as_deref());
139	
140	        let mut steps = HashMap::new();
141	        for (name, step_config) in &config.steps {
142	            let mut resolved = if let Some(template_name) = &step_config.template {
143	                let (template, _source) = registry.resolve(template_name)?;
144	                ResolvedStep::from_template(
145	                    name,
146	                    template,
147	                    step_config,
148	                    &step_config.inputs,
149	                    environment,
150	                )
151	            } else {
152	                ResolvedStep::from_config(name, step_config, environment)
153	            };
154	
155	            // Apply global defaults for fields that weren't explicitly set at step level
156	            if step_config.behavior.auto_run.is_none() {
157	                resolved.behavior.auto_run = defaults.auto_run;
158	            }
159	            if step_config.behavior.prompt_on_rerun.is_none() {
160	                resolved.behavior.prompt_on_rerun = defaults.prompt_on_rerun;
161	            }
162	            if step_config.behavior.rerun_window.is_none() {
163	                if let Some(window_str) = global_rerun_window {
164	                    if let Ok(w) = window_str.parse() {
165	                        resolved.behavior.rerun_window = w;
166	                    }
167	                }
168	            }
169	
170	            steps.insert(name.clone(), resolved);
171	        }
172	        Ok(steps)
173	    }
174	}
175	
176	/// Combine CLI force flags with the matching workflow's force directives.
177	///
178	/// Force is monotonic — any source can opt a step in — so the result is
179	/// the union of `--force <steps>` / `workflow.force` and the OR of
180	/// `--force-all` / `workflow.force_all`. Returns `(force_steps, force_all)`.
181	pub(crate) fn merge_force_directives(
182	    args: &RunArgs,
183	    workflow: Option<&crate::config::WorkflowConfig>,
184	) -> (HashSet<String>, bool) {
185	    let mut force: HashSet<String> = args.force.iter().cloned().collect();
186	    let mut force_all = args.force_all;
187	    if let Some(workflow) = workflow {
188	        force.extend(workflow.force.iter().cloned());
189	        force_all = force_all || workflow.force_all;
190	    }
191	    (force, force_all)
192	}
193	
194	impl Command for RunCommand {
195	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
196	        // Load configuration — use override path if provided, otherwise
197	        // perform a two-phase load that resolves the workflow name first
198	        // (using only `.bivvy/config.yml`), then deep-merges with only the
199	        // named workflow file in the chain.
200	        let config = if let Some(ref override_path) = self.config_override {
201	            match crate::config::load_config_file(override_path) {
202	                Ok(c) => c,
203	                Err(e) => {
204	                    ui.error(&format!(
205	                        "Failed to load config from {}: {}",
206	                        override_path.display(),
207	                        e
208	                    ));
209	                    return Ok(CommandResult::failure(2));
210	                }
211	            }
212	        } else {
213	            // Phase 1: load only `.bivvy/config.yml` so we can resolve the
214	            // workflow name against the active environment's `default_workflow`
215	            // and surface "workflow not found" errors before walking the
216	            // full merge chain.
217	            let phase1 = match load_project_config(&self.project_root) {
218	                Ok(c) => c,
219	                Err(BivvyError::ConfigNotFound { .. }) => {
220	                    ui.error("No configuration found. Run 'bivvy init' first.");
221	                    return Ok(CommandResult::failure(2));
222	                }
223	                Err(e) => return Err(e),
224	            };
225	
226	            // Resolve the workflow name using the project file's environments.
227	            let phase1_env = ResolvedEnvironment::resolve_from_config(
228	                self.args.env.as_deref(),
229	                &phase1.settings,
230	            );
231	            let resolved_name = if self.args.workflow == "default" {
232	                phase1
233	                    .settings
234	                    .environment_profiles
235	                    .environments
236	                    .get(&phase1_env.name)
237	                    .and_then(|env_config| env_config.default_workflow.clone())
238	                    .unwrap_or_else(|| self.args.workflow.clone())
239	            } else {
240	                self.args.workflow.clone()
241	            };
242	
243	            // Validate the resolved workflow exists somewhere bivvy will look.
244	            let discovery = Discovery::new(&self.project_root);
245	            let workflow_known = phase1.workflows.contains_key(&resolved_name)
246	                || discovery
247	                    .workflow_names()
248	                    .iter()
249	                    .any(|n| n == &resolved_name);
250	            if !workflow_known {
251	                let mut available: Vec<String> = phase1.workflows.keys().cloned().collect();
252	                available.extend(discovery.workflow_names());
253	                available.sort();
254	                available.dedup();
255	                let hint = if available.is_empty() {
256	                    String::new()
257	                } else {
258	                    format!(" Available: {}", available.join(", "))
259	                };
260	                ui.error(&format!("Unknown workflow: {}.{}", resolved_name, hint));
261	                return Ok(CommandResult::failure(1));
262	            }
263	
264	            // Phase 2: full merge with only the named workflow file in the chain.
265	            let trust_store_path = TrustStore::default_path();
266	            let resolver = ExtendsResolver::default();
267	            match load_for_run_with_trust(
268	                &self.project_root,
269	                &resolved_name,
270	                &resolver,
271	                self.trust_policy,
272	                &trust_store_path,
273	                ui,
274	            ) {
275	                Ok(c) => c,
276	                Err(BivvyError::ConfigNotFound { .. }) => {
277	                    ui.error("No configuration found. Run 'bivvy init' first.");
278	                    return Ok(CommandResult::failure(2));
279	                }
280	                Err(e) => return Err(e),
281	            }
282	        };
283	
284	        // Deprecation warning for --ci flag
285	        if self.args.ci {
286	            ui.warning(
287	                "--ci is deprecated and will be removed in 2.0. \
288	                 Use --non-interactive and --env ci instead.",
289	            );
290	        }
291	
292	        // Collect and display config deprecation warnings
293	        let mut deprecation_warnings =
294	            crate::lint::rules::deprecated_fields::collect_deprecation_warnings(&config);
295	
296	        // Scan raw YAML for alias-based deprecations (e.g., old field names)
297	        {
298	            let config_file_paths: Vec<std::path::PathBuf> =
299	                if let Some(ref p) = self.config_override {
300	                    vec![p.clone()]
301	                } else {
302	                    let paths = ConfigPaths::discover(&self.project_root);
303	                    paths
304	                        .all_existing()
305	                        .iter()
306	                        .map(|p| p.to_path_buf())
307	                        .collect()
308	                };
309	            let refs: Vec<&std::path::Path> =
310	                config_file_paths.iter().map(|p| p.as_path()).collect();
311	            deprecation_warnings.extend(
312	                crate::lint::rules::deprecated_fields::collect_raw_yaml_deprecation_warnings(&refs),
313	            );
314	        }
315	
316	        for warning in &deprecation_warnings {
317	            ui.warning(warning);
318	        }
319	
320	        // Apply config default_output when no CLI flag was explicitly set.
321	        // OutputMode::Normal means the user didn't pass --verbose or --quiet.
322	        if ui.output_mode() == OutputMode::Normal {
323	            ui.set_output_mode(config.settings.defaults.output.into());
324	        }
325	
326	        // Resolve environment (before header so we can use resolved workflow)
327	        let resolved_env = self.resolve_environment(&config);
328	        let env_name = resolved_env.name.clone();
329	
330	        // Warn if the environment is not known
331	        if !resolved_env.is_known(&config) {
332	            ui.warning(&format!(
333	                "Unknown environment '{}'. It is not defined in settings.environments                  or a built-in. Step overrides for this environment will have no effect.",
334	                env_name
335	            ));
336	        }
337	
338	        // Get provided_requirements from environment config
339	        let provided_requirements: HashSet<String> = config
340	            .settings
341	            .environment_profiles
342	            .environments
343	            .get(&env_name)
344	            .map(|env_config| env_config.provided_requirements.iter().cloned().collect())
345	            .unwrap_or_default();
346	
347	        // Use environment's default_workflow if no explicit --workflow and config has one
348	        let workflow_name = if self.args.workflow == "default" {
349	            config
350	                .settings
351	                .environment_profiles
352	                .environments
353	                .get(&env_name)
354	                .and_then(|env_config| env_config.default_workflow.clone())
355	                .unwrap_or_else(|| self.args.workflow.clone())
356	        } else {
357	            self.args.workflow.clone()
358	        };
359	
360	        // Build the run header (header rendering happens through the
361	        // workflow display so it stays coordinated with the pinned bar).
362	        let app_name = config.app_name.as_deref().unwrap_or("project").to_string();
363	        let step_count = config
364	            .workflows
365	            .get(workflow_name.as_str())
366	            .map(|w| w.steps.len())
367	            .unwrap_or(0);
368	        let run_header = RunHeader {
369	            app_name,
370	            version: crate::updates::version::VERSION.to_string(),
371	            workflow: workflow_name.clone(),
372	            step_count,
373	            env_name: env_name.clone(),
374	        };
375	
376	        // Construct the workflow display. Interactive runs get a
377	        // TerminalSurface that the UI shares so all output stays
378	        // above the pinned bar. `TerminalSurface::try_new` returns
379	        // `None` on dumb terminals (TERM=dumb, NO_COLOR, non-TTY stderr)
380	        // because indicatif silently hides MultiProgress output in
381	        // those cases — falling through to NonInteractiveWorkflowDisplay
382	        // ensures plain text output still reaches the user.
383	        let surface: Option<std::sync::Arc<TerminalSurface>> = if ui.is_interactive() {
384	            TerminalSurface::try_new()
385	        } else {
386	            None
387	        };
388	        let mut workflow_display: Box<dyn WorkflowDisplay> = match surface.as_ref() {
389	            Some(s) => Box::new(TerminalWorkflowDisplay::new(
390	                std::sync::Arc::clone(s),
391	                ui.output_mode(),
392	            )),
393	            None => Box::new(NonInteractiveWorkflowDisplay::new(ui.output_mode())),
394	        };
395	
396	        // Attach the surface to the existing UI so its output flows
397	        // through the surface (above the pinned bar) for the run.
398	        if let Some(s) = &surface {
399	            ui.attach_surface(std::sync::Arc::clone(s));
400	        }
401	
402	        if !self.args.suppress_header {
403	            workflow_display.show_run_header(&run_header);
404	        }
405	
406	        if self.args.dry_run {
407	            let theme = if crate::ui::should_use_colors() {
408	                crate::ui::BivvyTheme::new()
409	            } else {
410	                crate::ui::BivvyTheme::plain()
411	            };
412	            ui.message("");
413	            ui.message(
414	                &theme
415	                    .error
416	                    .apply_to("Running in dry-run mode - no commands will be executed")
417	                    .to_string(),
418	            );
419	            ui.message("");
420	        }
421	
422	        // Get project identity
423	        let project_id = ProjectId::from_path(&self.project_root)?;
424	
425	        // Load state (with any v1→v2 baseline migrations)
426	        let (mut state, baseline_migrations) = StateStore::load(&project_id)?;
427	
428	        // Resolve steps with environment
429	        let steps = self.resolve_steps(&config, Some(&env_name))?;
430	
431	        // Check if workflow exists
432	        if !config.workflows.contains_key(&workflow_name) {
433	            ui.error(&format!("Unknown workflow: {}", workflow_name));
434	            return Ok(CommandResult::failure(1));
435	        }
436	
437	        // Extract workflow-level non_interactive setting
438	        let workflow_non_interactive = config
439	            .workflows
440	            .get(&workflow_name)
441	            .and_then(|w| w.settings.as_ref())
442	            .is_some_and(|s| s.non_interactive);
443	
444	        // Extract step overrides from workflow config
445	        let workflow_config = config.workflows.get(&workflow_name);
446	        let mut step_overrides = workflow_config
447	            .map(|w| w.overrides.clone())
448	            .unwrap_or_default();
449	
450	        // Apply workflow-level auto_run_steps to step overrides (individual overrides take precedence)
451	        if let Some(wf) = workflow_config {
452	            if let Some(wf_auto_run) = wf.auto_run_steps {
453	                for step_name in &wf.steps {
454	                    let entry = step_overrides.entry(step_name.clone()).or_default();
455	                    if entry.auto_run.is_none() {
456	                        entry.auto_run = Some(wf_auto_run);
457	                    }
458	                }
459	            }
460	        }
461	
462	        // Build run options with resolved workflow and provided requirements
463	        let mut options = self.build_options(&config);
464	        options.workflow = Some(workflow_name.clone());
465	        options.provided_requirements = provided_requirements;
466	        options.active_environment = Some(env_name.clone());
467	
468	        // Create runner with project-backed snapshot store for change check baselines
469	        let mut snapshot_store = crate::snapshots::SnapshotStore::load_for_project(&project_id);
470	
471	        // Apply v1 baseline migrations into snapshot store
472	        for migration in &baseline_migrations {
473	            use crate::snapshots::SnapshotKey;
474	            let key = SnapshotKey::project(&migration.step_name, "v1_migrated");
475	            snapshot_store.record_baseline(
476	                &key,
477	                "_last_run",
478	                migration.hash.clone(),
479	                format!(
480	                    "migrated from v1 watches_hash for step '{}'",
481	                    migration.step_name
482	                ),
483	            );
484	        }
485	
486	        let mut runner = WorkflowRunner::with_snapshot_store(&config, steps, snapshot_store);
487	
488	        // Create gap checker for requirement detection
489	        let probe = EnvironmentProbe::run();
490	        let req_registry = RequirementRegistry::new().with_custom(&config.requirements);
491	        let mut gap_checker = GapChecker::new(&req_registry, &probe, &self.project_root);
492	
493	        // Evaluate user-defined vars
494	        let resolved_vars = evaluate_vars(&config.vars, &self.project_root)?;
495	
496	        // Create interpolation context
497	        let ctx = InterpolationContext::new().with_vars(resolved_vars);
498	
499	        // Build the YAML-defined base env (settings.env_vars + workflow env),
500	        // then snapshot the parent process env. The base env is layered first
501	        // and the process env wins last in the executor (see
502	        // `bivvy::steps::build_step_env`), so shell-exported variables
503	        // override anything declared in YAML.
504	        let base_env =
505	            crate::config::build_yaml_env_stack(&config, &workflow_name, &self.project_root)?
506	                .resolve();
507	        let process_env: HashMap<String, String> = std::env::vars().collect();
508	
509	        // Create event bus with logger for structured event logging
510	        let mut event_bus = crate::logging::EventBus::new();
511	        if config.settings.logging.logging {
512	            if let Ok(mut logger) = crate::logging::EventLogger::new(
513	                crate::logging::default_log_dir(),
514	                &format!(
515	                    "sess_{}_{}",
516	                    chrono::Utc::now().format("%Y%m%d%H%M%S"),
517	                    &project_id.hash()[..8]
518	                ),
519	                config.settings.logging.to_retention_policy(),
520	            ) {
521	                // Register sensitive steps for redaction
522	                let sensitive: Vec<String> = config
523	                    .steps
524	                    .iter()
525	                    .filter(|(_, s)| s.behavior.sensitive)
526	                    .map(|(name, _)| name.clone())
527	                    .collect();
528	                logger.set_sensitive_steps(sensitive);
529	                event_bus.add_consumer(Box::new(logger));
530	            }
531	        }
532	
533	        // Emit session started
534	        event_bus.emit(&crate::logging::BivvyEvent::SessionStarted {
535	            command: "run".to_string(),
536	            args: vec![workflow_name.clone()],
537	            version: crate::updates::version::VERSION.to_string(),
538	            os: Some(std::env::consts::OS.to_string()),
539	            working_directory: Some(self.project_root.display().to_string()),
540	        });
541	
542	        // Emit config loaded
543	        {
544	            let config_path = if let Some(ref override_path) = self.config_override {
545	                override_path.display().to_string()
546	            } else {
547	                let paths = ConfigPaths::discover(&self.project_root);
548	                paths
549	                    .project
550	                    .map(|p| p.display().to_string())
551	                    .unwrap_or_else(|| ".bivvy/config.yml".to_string())
552	            };
553	            event_bus.emit(&crate::logging::BivvyEvent::ConfigLoaded {
554	                config_path,
555	                parse_duration_ms: None,
556	                deprecation_warnings: deprecation_warnings.clone(),
557	            });
558	        }
559	
560	        // Initialize satisfaction cache (two-layer: persisted + runtime)
561	        let mut satisfaction_cache = if options.fresh {
562	            crate::state::SatisfactionCache::empty(project_id.satisfaction_path())
563	        } else {
564	            crate::state::SatisfactionCache::load(project_id.satisfaction_path())
565	        };
566	
567	        // Run the workflow with UI-driven interactive prompts
568	        let result = runner.run_with_ui(
569	            &options,
570	            &ctx,
571	            &base_env,
572	            &process_env,
573	            &self.project_root,
574	            workflow_non_interactive,
575	            &step_overrides,
576	            Some(&mut gap_checker),
577	            Some(&mut state),
578	            &mut satisfaction_cache,
579	            ui,
580	            workflow_display.as_mut(),
581	            &mut event_bus,
582	        )?;
583	
584	        // Update state and snapshots (unless dry-run)
585	        if !self.args.dry_run {
586	            // Record step results into state store. Only steps that actually
587	            // executed update state — check-passed and skipped results don't
588	            // represent a run, so overwriting `last_run` would mis-report the
589	            // last execution time on subsequent runs.
590	            for step_result in &result.steps {
591	                if !step_result.actually_executed() {
592	                    continue;
593	                }
594	                let status = match step_result.status() {
595	                    crate::steps::StepStatus::Completed => crate::state::StepStatus::Success,
596	                    crate::steps::StepStatus::Failed => crate::state::StepStatus::Failed,
597	                    _ => crate::state::StepStatus::NeverRun,
598	                };
599	                state.record_step_result(&step_result.name, status, step_result.duration);
600	            }
601	
602	            state.save(&project_id)?;
603	
604	            // Save snapshot baselines accumulated during check evaluation
605	            if let Err(e) = runner.snapshot_store_mut().save() {
606	                tracing::warn!("Failed to save snapshot store: {}", e);
607	            }
608	        }
609	
610	        // Build and show run summary
611	        let steps_satisfied = result.steps.iter().filter(|s| s.was_check_passed()).count();
612	        let steps_run = result.steps.len();
613	        let steps_skipped = result.skipped.len();
614	        let failed_steps: Vec<String> = result
615	            .steps
616	            .iter()
617	            .filter(|s| !s.success && !s.skipped)
618	            .map(|s| s.name.clone())
619	            .collect();
620	
621	        let step_results: Vec<StepSummary> = result
622	            .steps
623	            .iter()
624	            .map(|s| StepSummary {
625	                name: s.name.clone(),
626	                status: StatusKind::from(s.status()),
627	                duration: if s.duration.as_millis() > 0 {
628	                    Some(s.duration)
629	                } else {
630	                    None
631	                },
632	                detail: if let Some(ref rd) = s.recovery_detail {
633	                    Some(rd.clone())
634	                } else if s.skipped {
635	                    Some(
636	                        s.check_result
637	                            .as_ref()
638	                            .map(|c| c.description.clone())
639	                            .unwrap_or_else(|| "already complete".to_string()),
640	                    )
641	                } else if s.success && s.check_result.is_some() && s.duration.as_millis() == 0 {
642	                    // check_passed result: show what check determined completion
643	                    Some(
644	                        s.check_result
645	                            .as_ref()
646	                            .map(|c| format!("Check passed ({})", c.description))
647	                            .unwrap_or_else(|| "Check passed".to_string()),
648	                    )
649	                } else if !s.success && !s.skipped {
650	                    s.error.clone()
651	                } else {
652	                    None
653	                },
654	            })
655	            .collect();
656	
657	        let summary = RunSummary {
658	            step_results,
659	            total_duration: result.duration,
660	            steps_run,
661	            steps_skipped,
662	            steps_satisfied,
663	            success: result.success,
664	            failed_steps: failed_steps.clone(),
665	        };
666	
667	        workflow_display.show_run_summary(&summary);
668	
669	        // Show contextual hint and emit session ended
670	        let (exit_code, cmd_result) = if result.success {
671	            workflow_display.hint(hints::after_successful_run());
672	            (0, CommandResult::success())
673	        } else if result.aborted {
674	            workflow_display.hint("Workflow aborted by user. Re-run to resume.");
675	            (1, CommandResult::failure(1))
676	        } else {
677	            workflow_display.hint(&hints::after_failed_run(&failed_steps));
678	            (1, CommandResult::failure(1))
679	        };
680	
681	        // Detach the surface from the UI now that the run is complete.
682	        ui.detach_surface();
683	
684	        event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
685	            exit_code,
686	            duration_ms: result.duration.as_millis() as u64,
687	        });
688	
689	        Ok(cmd_result)
690	    }
691	}
