    #[test]
    fn build_options_diagnostic_funnel_defaults_to_config_value() {
        let temp = TempDir::new().unwrap();
        let args = RunArgs::default();
        let cmd = RunCommand::new(temp.path(), args);

        // Default config has diagnostic_funnel = true
        let config = crate::config::BivvyConfig::default();
        let options = cmd.build_options(&config);
        assert!(options.diagnostic_funnel);

        // Config with diagnostic_funnel = false
        let mut config_off = crate::config::BivvyConfig::default();
        config_off.settings.execution.diagnostic_funnel = false;
        let options = cmd.build_options(&config_off);
        assert!(!options.diagnostic_funnel);
    }

    #[test]
    fn build_options_diagnostic_funnel_cli_flag_overrides_config() {
        let temp = TempDir::new().unwrap();

        // --diagnostic-funnel forces on even when config says false
        let args = RunArgs {
            diagnostic_funnel: true,
            ..Default::default()
        };
        let cmd = RunCommand::new(temp.path(), args);
        let mut config = crate::config::BivvyConfig::default();
        config.settings.execution.diagnostic_funnel = false;
        let options = cmd.build_options(&config);
        assert!(options.diagnostic_funnel);

        // --no-diagnostic-funnel forces off even when config says true
        let args = RunArgs {
            no_diagnostic_funnel: true,
            ..Default::default()
        };
        let cmd = RunCommand::new(temp.path(), args);
        let config = crate::config::BivvyConfig::default();
        let options = cmd.build_options(&config);
        assert!(!options.diagnostic_funnel);
    }

    #[test]
    fn merge_force_directives_no_workflow_uses_cli_only() {
        let args = RunArgs {
            force: vec!["a".to_string()],
            force_all: false,
            ..Default::default()
        };
        let (force, force_all) = merge_force_directives(&args, None);
        assert_eq!(force, ["a".to_string()].into_iter().collect());
        assert!(!force_all);
    }

    #[test]
    fn merge_force_directives_unions_force_lists() {
        let args = RunArgs {
            force: vec!["cli_step".to_string()],
            ..Default::default()
        };
        let workflow = crate::config::WorkflowConfig {
            force: vec!["workflow_step".to_string()],
            ..Default::default()
        };
        let (force, force_all) = merge_force_directives(&args, Some(&workflow));
        assert!(force.contains("cli_step"));
        assert!(force.contains("workflow_step"));
        assert_eq!(force.len(), 2);
        assert!(!force_all);
    }

    #[test]
    fn merge_force_directives_workflow_force_all_propagates() {
        let args = RunArgs {
            force_all: false,
            ..Default::default()
        };
        let workflow = crate::config::WorkflowConfig {
            force_all: true,
            ..Default::default()
        };
        let (_force, force_all) = merge_force_directives(&args, Some(&workflow));
        assert!(force_all);
    }

    #[test]
    fn merge_force_directives_cli_force_all_overrides_workflow_default() {
        let args = RunArgs {
            force_all: true,
            ..Default::default()
        };
        let workflow = crate::config::WorkflowConfig {
            force_all: false,
            ..Default::default()
        };
        let (_force, force_all) = merge_force_directives(&args, Some(&workflow));
        assert!(force_all);
    }

    #[test]
    fn config_diagnostic_funnel_deserialization() {
        let yaml = r#"
app_name: test
settings:
  diagnostic_funnel: false
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let config: crate::config::BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(!config.settings.execution.diagnostic_funnel);

        // Omitted means true (default)
        let yaml_default = r#"
app_name: test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let config: crate::config::BivvyConfig = serde_yaml::from_str(yaml_default).unwrap();
        assert!(config.settings.execution.diagnostic_funnel);
    }
}

