    name: self.step_name.to_string(),
    decision: "run".to_string(),
    reason: None,
    trace: Some(DecisionTrace {
        behavior_flags: make_behavior_flags(self.step, needs_force),
        ..Default::default()
    }),
});
event_bus.emit(&BivvyEvent::StepStarting {
    name: self.step_name.to_string(),
});

