    let mut outcomes = HashMap::new();
    for r in results {
        outcomes.insert(r.name.clone(), r.status());
    }
    for s in satisfied_steps {
        outcomes.entry(s.clone()).or_insert(StepStatus::Completed);
    }
    for s in failed_steps {
