    self.step_name,
    &step_number,
    step_indent,
    opts.project_root,
    context,
    opts.base_env,
    opts.process_env,
    needs_force,
    opts.dry_run,
    opts.interactive,
    &step_ctx,
    opts.diagnostic_funnel,
    &ws,
    ui,
    step_display,
    event_bus,
