114	    pub fn with_snapshot_store(
115	        config: &'a BivvyConfig,
116	        steps: HashMap<String, ResolvedStep>,
117	        snapshot_store: SnapshotStore,
118	    ) -> Self {
119	        Self {
120	            config,
121	            steps,
122	            snapshot_store,
123	        }
124	    }
