131	    /// Run the specified workflow.
132	    ///
133	    /// `base_env` is the YAML-derived env stack (settings + workflow), already
134	    /// merged in priority order. `process_env` is the parent process
135	    /// environment, which wins over both `base_env` and any step-level env.
136	    #[allow(clippy::too_many_arguments)]
137	    pub fn run(
138	        &mut self,
139	        options: &RunOptions,
140	        context: &InterpolationContext,
141	        base_env: &HashMap<String, String>,
142	        process_env: &HashMap<String, String>,
143	        project_root: &Path,
144	    ) -> Result<WorkflowResult> {
145	        let mut event_bus = EventBus::new();
146	        self.run_with_progress(
147	            options,
148	            context,
