159	    /// Run the specified workflow with a progress callback.
160	    #[allow(clippy::too_many_arguments)]
161	    pub fn run_with_progress(
162	        &mut self,
163	        options: &RunOptions,
164	        context: &InterpolationContext,
165	        base_env: &HashMap<String, String>,
166	        process_env: &HashMap<String, String>,
167	        project_root: &Path,
168	        mut gap_checker: Option<&mut GapChecker<'_>>,
169	        mut state: Option<&mut StateStore>,
170	        mut on_progress: impl FnMut(RunProgress<'_>),
171	        _event_bus: &mut EventBus,
172	    ) -> Result<WorkflowResult> {
173	        let start = Instant::now();
174	        let workflow_name = options.workflow.as_deref().unwrap_or("default");
175	
176	        // Build dependency graph and execution plan
177	        let graph = self.build_graph(workflow_name)?;
178	        let workflow_steps = &self.config.workflows[workflow_name].steps;
179	        let plan = build_execution_plan(&graph, workflow_steps, options, &self.steps)?;
180	
181	        let total = plan.steps_to_run.len();
182	
183	        // Report skipped steps
184	        for skip_name in &plan.flag_skipped {
185	            on_progress(RunProgress::StepSkipped { name: skip_name });
186	        }
187	        for skip_name in &plan.env_skipped {
188	            on_progress(RunProgress::StepSkipped { name: skip_name });
189	        }
190	
191	        let mut results = Vec::new();
192	        let mut all_success = true;
193	        let mut failed_steps: HashSet<String> = HashSet::new();
194	
195	        for (index, step_name) in plan.steps_to_run.iter().enumerate() {
196	            let step =
197	                self.steps
198	                    .get(step_name)
199	                    .ok_or_else(|| BivvyError::ConfigValidationError {
200	                        message: format!("Step '{}' not found in resolved steps", step_name),
201	                    })?;
202	
203	            // Check if any dependency failed
204	            if decision::blocked_by_failure(step, &failed_steps) {
205	                on_progress(RunProgress::StepSkipped { name: step_name });
206	                all_success = false;
207	                failed_steps.insert(step_name.clone());
208	                continue;
209	            }
210	
211	            // Check requirement gaps (non-UI: any blocking gap is an error)
212	            if let Some(ref mut checker) = gap_checker {
213	                let provided = if options.provided_requirements.is_empty() {
214	                    None
215	                } else {
216	                    Some(&options.provided_requirements)
217	                };
218	                let gaps = checker.check_step(step, provided);
219	                let blocking: Vec<_> = gaps
220	                    .iter()
221	                    .filter(|g| !g.status.is_satisfied() && !g.status.can_proceed())
222	                    .collect();
223	                if !blocking.is_empty() {
224	                    let names: Vec<_> = blocking.iter().map(|g| g.requirement.as_str()).collect();
225	                    return Err(BivvyError::RequirementMissing {
226	                        requirement: names.join(", "),
227	                        message: format!(
228	                            "Step '{}' requires: {}. Run 'bivvy lint' for details.",
229	                            step_name,
230	                            names.join(", ")
231	                        ),
232	                    });
233	                }
234	            }
235	
236	            // Evaluate precondition using the new CheckEvaluator (never bypassed by --force)
237	            if let Some(precondition) = step.execution.effective_precondition() {
238	                let mut evaluator =
239	                    CheckEvaluator::new(project_root, context, &mut self.snapshot_store);
240	                let precond_result = evaluator.evaluate(&precondition);
241	                if !precond_result.passed_check() {
242	                    return Err(BivvyError::StepExecutionError {
243	                        step: step_name.clone(),
244	                        message: format!("Precondition failed: {}", precond_result.description),
245	                    });
246	                }
247	            }
248	
249	            // Evaluate completed check using the new CheckEvaluator
250	            if !options.should_force(step_name) && !step.behavior.force {
251	                if let Some(check) = step.execution.effective_check() {
252	                    let config_hash = check.config_hash();
253	                    let mut evaluator =
254	                        CheckEvaluator::new(project_root, context, &mut self.snapshot_store)
255	                            .with_step(step_name, &config_hash)
256	                            .with_workflow(workflow_name);
257	                    let check_result = evaluator.evaluate(&check);
258	                    if check_result.passed_check() {
259	                        let skip_result = StepResult::skipped(step_name, check_result);
260	                        on_progress(RunProgress::StepFinished {
261	                            name: step_name,
262	                            result: &skip_result,
263	                        });
264	                        results.push(skip_result);
265	                        continue;
266	                    }
267	                }
268	            }
269	
270	            on_progress(RunProgress::StepStarting {
271	                name: step_name,
272	                index,
273	                total,
274	            });
275	
276	            let exec_options = ExecutionOptions {
277	                force: options.should_force(step_name) || step.behavior.force,
278	                dry_run: options.dry_run,
